206|        'fetch(U,{cache:"no-cache"}).then(function(r){return r.text();}).then(function(t){',
207|          'if(h(t)!==B){',
208|            'var d=document.createElement("div");',
209|            'd.textContent="\\u26A0\\uFE0F Claude Chat Exporter: update available \\u2014 click to re-grab";',
210|            'd.style.cssText="position:fixed;top:10px;right:10px;z-index:10001;background:#d97757;color:#1a1a1a;padding:8px 12px;border-radius:6px;font:12px/1.4 monospace;cursor:pointer;box-shadow:0 2px 10px rgba(0,0,0,.3);max-width:300px";',
