{"content": "1|// Claude Chat Exporter — exports a claude.ai conversation to a markdown file.
2|//
3|// Approach: read the conversation straight from claude.ai's own internal API
4|// (the same endpoint the app uses), which returns every message's *source
5|// markdown* — tables, math, code, and all — in order, complete, with an explicit
6|// human/assistant label. There is no DOM scraping, no copy-button clicking, no
7|// clipboard interception, and no scrolling: a single same-origin fetch (using the
8|// user's existing session) is transformed into markdown and downloaded.
9|//
10|// Why not the DOM? The rendered page is a lossy derivative of this markdown, only
11|// shows a virtualized window of long conversations, and couples the script to
12|// CSS selectors that change constantly. The API is a far more stable data
13|// contract. See CLAUDE.md for the response shape.
14|function setupClaudeExporter() {
15|  let conversationData = null;
16|
17|  // Non-fatal warnings collected during the run — logged to the console and
18|  // summarised in the status box, so a degraded export never looks fully clean.
19|  const warnings = [];
20|  const warn = (msg) => { console.warn(msg); warnings.push(msg); };
21|  // tool_use names that were skipped (not rendered) — logged once, to help spot a
22|  // new content-bearing tool the registry should learn about.
23|  const skippedTools = new Set();
24|
25|  function downloadMarkdown(content, filename) {
26|    const blob = new Blob([content], { type: 'text/markdown' });
27|    const a = document.createElement('a');
28|    a.href = URL.createObjectURL(blob);
29|    try {
30|      a.download = filename;
31|      document.body.appendChild(a);
32|      a.click();
33|      document.body.removeChild(a);
34|    } finally {
35|      URL.revokeObjectURL(a.href); // revoke even if the click throws (avoids a leak)
36|    }
37|  }
38|
39|  // Format ISO timestamp to a readable format
40|  function formatTimestamp(isoString) {
41|    if (!isoString) return null;
42|    const date = new Date(isoString);
43|    if (isNaN(date.getTime())) return null; // don't leak "Invalid Date" into a header
44|    return date.toLocaleString('en-US', {
45|      month: 'short', day: 'numeric', year: 'numeric',
46|      hour: 'numeric', minute: '2-digit'
47|    });
48|  }
49|
50|  // Fetch the full conversation from Claude's internal API. Same-origin request
51|  // authenticated by the user's existing session cookie; returns title, ordered
52|  // messages, per-message timestamps and content blocks. See CLAUDE.md.
53|  async function fetchConversationData() {
54|    const conversationId = window.location.pathname.split('/').pop();
55|    const orgId = document.cookie.match(/lastActiveOrg=([^;]+)/)?.[1];
56|
57|    // A Claude conversation id is a UUID; anything else (e.g. /new, /projects) means
58|    // the user isn't on a specific conversation.
59|    if (!conversationId || conversationId.length < 20 || !conversationId.includes('-')) {
60|      throw new Error('Open a specific Claude conversation first (the current page has no conversation id).');
61|    }
62|    if (!orgId) {
63|      throw new Error("Couldn't read your Claude session (lastActiveOrg cookie missing) — are you signed in?");
64|    }
65|
66|    const url = `/api/organizations/${orgId}/chat_conversations/${conversationId}?tree=true&rendering_mode=messages&render_all_tools=true`;
67|
68|    let response;
69|    try {
70|      response = await fetch(url, {
71|        credentials: 'include',
72|        headers: { 'Content-Type': 'application/json' }
73|      });
74|    } catch (error) {
75|      throw new Error(`Couldn't reach the Claude API: ${error.message}`);
76|    }
77|
78|    if (!response.ok) {
79|      const hint = (response.status === 401 || response.status === 403)
80|        ? ' — your session may have expired; reload and sign in'
81|        : '';
82|      throw new Error(`Claude API request failed (HTTP ${response.status})${hint}.`);
83|    }
84|
85|    try {
86|      return await response.json();
87|    } catch (error) {
88|      throw new Error(`Couldn't parse the Claude API response: ${error.message}`);
89|    }
90|  }
91|
92|  // Turn the API response into an ordered list of visible turns:
93|  // [{ sender, text, created_at, truncated, stop_reason }] in conversation order.
94|  //
95|  // Ordering: the API returns a message *tree*. We follow the current branch by
96|  // walking from current_leaf_message_uuid up the parent_message_uuid chain and
97|  // reversing — this exports exactly the path shown on screen even when a
98|  // response was regenerated. Falls back to sorting by `index` if the leaf is
99|  // missing.
100|  //
101|  // Content: a message's `content` is an array of typed blocks (text, thinking,
102|  // tool_use, tool_result). We walk them in order, emitting `text` blocks plus the
103|  // content-bearing `tool_use` blocks (artifacts / created files / widgets, via
104|  // renderToolUse) so text and special elements stay interleaved; `thinking` and
105|  // `tool_result` are skipped. Messages that end up empty are dropped (the API also
106|  // returns hidden/system messages the UI never shows).
107|  function getOrderedMessages(data) {
108|    const all = data?.chat_messages || [];
109|    if (!all.length) return [];
110|
111|    const byUuid = new Map(all.map(m => [m.uuid, m]));
112|    let ordered = null;
113|
114|    const leaf = data.current_leaf_message_uuid;
115|    if (leaf && byUuid.has(leaf)) {
116|      const path = [];
117|      const seen = new Set();
118|      let cur = byUuid.get(leaf);
119|      while (cur && !seen.has(cur.uuid)) {
120|        seen.add(cur.uuid);
121|        path.push(cur);
122|        cur = cur.parent_message_uuid ? byUuid.get(cur.parent_message_uuid) : null;
123|      }
124|      if (path.length) ordered = path.reverse();
125|    }
126|
127|    if (!ordered) {
128|      warn('Could not resolve the current branch (current_leaf_message_uuid missing/unresolved) — falling back to index order, which may be inaccurate for branched conversations.');
129|      ordered = [...all].sort((a, b) => (a.index ?? 0) - (b.index ?? 0));
130|    }
131|
132|    // Reconstruct each artifact's final state up-front so it can be rendered once,
133|    // at its last edit (see collectArtifacts / renderToolUse).
134|    const artifacts = collectArtifacts(ordered);
